/**
 * ProjectImage
 *
 * Renders a portfolio image through <picture> so browsers that support WebP
 * take the optimised sibling generated by scripts/optimize-images.mjs, while
 * everyone else keeps the original PNG.
 *
 * `fit` maps to object-fit; portrait artwork uses "contain" so it is not
 * cropped inside a landscape card.
 */
const toWebp = (src) => `/optimized/${src.replace(/^\//, '').replace(/\.(png|jpe?g)$/i, '.webp')}`;

export default function ProjectImage({
  src,
  alt,
  className = '',
  fit = 'cover',
  loading = 'lazy',
  ...props
}) {
  return (
    <picture>
      <source srcSet={toWebp(src)} type="image/webp" />
      <img
        src={src}
        alt={alt}
        loading={loading}
        decoding="async"
        className={className}
        style={{ objectFit: fit }}
        {...props}
      />
    </picture>
  );
}
